"""srt_reviser: LLM-based SRT transcription revision using context documents.

Parses SRT into blocks, sends ONLY the text content to the LLM (timestamps are
never touched), then reassembles the corrected SRT with original timestamps.

Why text-only approach?
  LLMs sometimes hallucinate timestamps or reformat SRT structure. By extracting
  just the text, sending it as a JSON map {index: text}, and merging back, we
  guarantee the SRT structure and all timestamps remain bit-for-bit identical.
"""
from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

from atcli.utils.logger import get_logger

logger = get_logger(__name__)

# Max subtitle blocks per LLM call — keeps prompt size manageable.
_BATCH_SIZE = 80


def revise_srt(
    srt_text: str,
    context_docs: list[str],
    hints: str = "",
    api_key: str = "",
    endpoint: str = "",
    model: str = "gpt-4o-mini",
) -> str:
    """Revise SRT transcription using LLM and optional context documents.

    Args:
        srt_text:     Raw SRT content to revise.
        context_docs: Paths to PDF/text reference documents.
        hints:        Free-text domain hints (topic, speaker names, etc.).
        api_key:      OpenAI-compatible API key.
        endpoint:     API base URL (default: OpenAI).
        model:        LLM model identifier.

    Returns:
        Revised SRT content with corrected text, original timestamps preserved.
    """
    blocks = _parse_srt(srt_text)
    if not blocks:
        return srt_text

    context_text = _build_context(context_docs, hints)
    logger.info("Revising %d subtitle blocks with %s...", len(blocks), model)

    # Process in batches to handle long files without exceeding context limits
    revised_texts: dict[str, str] = {}
    batch_count = 0
    for batch_start in range(0, len(blocks), _BATCH_SIZE):
        batch = blocks[batch_start : batch_start + _BATCH_SIZE]
        batch_map = {b["index"]: b["text"] for b in batch}
        batch_revised = _revise_batch(batch_map, context_text, api_key, endpoint, model)
        revised_texts.update(batch_revised)
        batch_count += 1
        logger.debug("Revised batch %d/%d", batch_count, -(-len(blocks) // _BATCH_SIZE))

    return _reassemble_srt(blocks, revised_texts)


def _parse_srt(srt_text: str) -> list[dict[str, str]]:
    """Parse SRT text into list of {index, timestamp, text} dicts."""
    blocks: list[dict[str, str]] = []
    for block in re.split(r"\n{2,}", srt_text.strip()):
        lines = block.strip().splitlines()
        if len(lines) < 3:
            continue
        # lines[0] = sequence number, lines[1] = timestamps, lines[2+] = text
        if not re.match(r"^\d+$", lines[0].strip()):
            continue
        blocks.append({
            "index": lines[0].strip(),
            "timestamp": lines[1].strip(),
            "text": "\n".join(lines[2:]),
        })
    return blocks


def _reassemble_srt(blocks: list[dict[str, str]], revised_texts: dict[str, str]) -> str:
    """Rebuild SRT string, replacing text with revised versions."""
    parts: list[str] = []
    for block in blocks:
        text = revised_texts.get(block["index"], block["text"])
        parts.append(f"{block['index']}\n{block['timestamp']}\n{text}")
    return "\n\n".join(parts) + "\n"


def _build_context(doc_paths: list[str], hints: str) -> str:
    """Combine document texts and hints into a context string for the prompt."""
    from atcli.core.context_extractor import extract_text_from_pdf

    parts: list[str] = []
    for path in doc_paths:
        try:
            if path.lower().endswith(".pdf"):
                text = extract_text_from_pdf(path)
            else:
                text = Path(path).read_text(encoding="utf-8", errors="ignore")
            if text.strip():
                # Limit per-doc to avoid bloating the prompt
                parts.append(f"[{Path(path).name}]\n{text[:6000]}")
        except Exception as exc:
            logger.warning("Skipping context doc %s: %s", path, exc)

    combined = "\n\n".join(parts)
    if hints:
        combined = f"{combined}\n\nHints: {hints}".strip()
    return combined


def _revise_batch(
    texts: dict[str, str],
    context_text: str,
    api_key: str,
    endpoint: str,
    model: str,
) -> dict[str, str]:
    """Call LLM to revise one batch of subtitle texts.

    Sends texts as JSON {index: text} and expects JSON back.
    Falls back to original texts if parsing fails.
    """
    texts_json = json.dumps(texts, ensure_ascii=False, indent=2)
    context_section = f"<context>\n{context_text}\n</context>\n\n" if context_text else ""

    prompt = f"""{context_section}You are a transcription editor. Correct errors in these subtitles from a speech recording.

Rules:
- Fix proper nouns, product/brand names, and technical terms using the context above
- Fix obvious mis-transcriptions (e.g. homophones, wrong words)
- Preserve the natural speech style, fillers (ờ, uh, hmm), and speaker's phrasing
- Return EXACTLY the same JSON structure: {{"index": "corrected text", ...}}
- Do NOT add, remove, or reorder entries
- Do NOT include explanations

Input JSON:
{texts_json}

Return corrected JSON only:"""

    raw = _call_llm(prompt, api_key, endpoint, model)

    # Extract JSON from response (LLM sometimes wraps in markdown)
    try:
        result = json.loads(raw)
        return {str(k): str(v) for k, v in result.items()}
    except json.JSONDecodeError:
        m = re.search(r"\{.*\}", raw, re.S)
        if m:
            try:
                result = json.loads(m.group(0))
                return {str(k): str(v) for k, v in result.items()}
            except json.JSONDecodeError:
                pass
    logger.warning("LLM returned unparseable response for batch, keeping originals.")
    return {}


def _call_llm(prompt: str, api_key: str, endpoint: str, model: str) -> str:
    """POST to an OpenAI-compatible chat completions endpoint."""
    import httpx

    base_url = (endpoint or "https://api.openai.com/v1").rstrip("/")
    url = f"{base_url}/chat/completions"

    resp = httpx.post(
        url,
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        json={
            "model": model,
            "messages": [{"role": "user", "content": prompt}],
            "temperature": 0.1,
        },
        timeout=120.0,
    )
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"].strip()
